# General Awareness: Indian Constitution and polity, and Indian history
# (ancient, medieval, modern). Static facts only: no current affairs and no
# current office-holders.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Fundamental Rights", "Which Article of the Constitution of India abolishes untouchability?",
      ["Article 17", "Article 14", "Article 21", "Article 32"],
      "Article 17 abolishes untouchability and forbids its practice in any form. Article 14 is equality before law, Article 21 is protection of life and personal liberty, and Article 32 is the right to constitutional remedies."),
    S(1, 1, "Making of the Constitution", "On which date did the Constituent Assembly adopt the Constitution of India?",
      ["26 November 1949", "26 January 1950", "15 August 1947", "9 December 1946"],
      "The Constitution was adopted on 26 November 1949, now observed as Constitution Day. It came fully into force on 26 January 1950. The Assembly first met on 9 December 1946."),
    S(1, 1, "Making of the Constitution", "Who was the chairman of the Drafting Committee of the Constituent Assembly?",
      ["B. R. Ambedkar", "Rajendra Prasad", "Jawaharlal Nehru", "Vallabhbhai Patel"],
      "Dr B. R. Ambedkar chaired the Drafting Committee. Dr Rajendra Prasad was the President of the Constituent Assembly."),
    S(1, 2, "Amendments", "The Fundamental Duties were added to the Constitution of India by which amendment?",
      ["42nd Amendment", "44th Amendment", "73rd Amendment", "86th Amendment"],
      "The 42nd Amendment Act of 1976 added Part IVA (Article 51A) with the Fundamental Duties, on the recommendation of the Swaran Singh Committee. The 86th Amendment later added an eleventh duty about education."),
    S(1, 1, "Parliament", "What is the minimum age to become a member of the Lok Sabha?",
      ["25 years", "30 years", "35 years", "21 years"],
      "Article 84 sets the minimum age at 25 years for the Lok Sabha and 30 years for the Rajya Sabha."),
    S(1, 2, "Writs", "Which writ is issued to free a person who has been detained unlawfully?",
      ["Habeas corpus", "Mandamus", "Certiorari", "Quo warranto"],
      "Habeas corpus ('to have the body') orders the detaining authority to produce the person before the court. Mandamus commands a public duty, certiorari quashes a lower court's order, and quo warranto questions the right to hold a public office."),
    S(1, 2, "Parliament", "Who presides over a joint sitting of the two Houses of Parliament?",
      ["The Speaker of the Lok Sabha", "The Vice-President", "The President", "The Prime Minister"],
      "Under Article 108 the President summons a joint sitting, but the Speaker of the Lok Sabha presides over it (Article 118)."),
    S(1, 1, "Ancient India", "Lothal, the Harappan site known for its dockyard, is in which present-day state?",
      ["Gujarat", "Rajasthan", "Punjab", "Haryana"],
      "Lothal is in Ahmedabad district, Gujarat. Kalibangan is in Rajasthan, Rakhigarhi in Haryana and Ropar in Punjab."),
    S(1, 1, "Ancient India", "Where did Gautama Buddha deliver his first sermon?",
      ["Sarnath", "Bodh Gaya", "Kushinagar", "Lumbini"],
      "The first sermon, the turning of the wheel of dharma, was at Sarnath near Varanasi. He attained enlightenment at Bodh Gaya, was born at Lumbini and died at Kushinagar."),
    S(1, 1, "Medieval India", "The First Battle of Panipat in 1526 was fought between Babur and:",
      ["Ibrahim Lodi", "Rana Sanga", "Hemu", "Sher Shah Suri"],
      "Babur defeated Ibrahim Lodi, the last Delhi Sultan, at Panipat in 1526 and founded Mughal rule. He fought Rana Sanga at Khanwa (1527), and Hemu lost the Second Battle of Panipat (1556)."),
    S(1, 2, "Medieval India", "Construction of the Qutb Minar in Delhi was begun by:",
      ["Qutb-ud-din Aibak", "Iltutmish", "Alauddin Khalji", "Balban"],
      "Qutb-ud-din Aibak began the Qutb Minar around 1199, and his successor Iltutmish added the upper storeys."),
    S(1, 1, "Modern India", "In which year did the Jallianwala Bagh massacre take place in Amritsar?",
      ["1919", "1920", "1915", "1922"],
      "The massacre took place on 13 April 1919, when troops under General Dyer fired on a peaceful gathering protesting the Rowlatt Act."),
    S(1, 2, "Modern India", "Who was the first president of the Indian National Congress, at its 1885 session in Bombay?",
      ["W. C. Bonnerjee", "A. O. Hume", "Dadabhai Naoroji", "Surendranath Banerjee"],
      "Womesh Chunder Bonnerjee presided over the first session in 1885. A. O. Hume helped found the Congress, and Dadabhai Naoroji presided in 1886."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Fundamental Rights", "Which Article of the Constitution of India gives the right to constitutional remedies?",
      ["Article 32", "Article 19", "Article 14", "Article 368"],
      "Article 32 lets a person go directly to the Supreme Court to enforce Fundamental Rights. Dr Ambedkar called it the heart and soul of the Constitution. Article 368 deals with amending the Constitution."),
    S(2, 2, "Preamble", "The 42nd Amendment of 1976 added which words to the Preamble?",
      ["Socialist, secular and integrity", "Sovereign, democratic and republic", "Justice, liberty and equality", "Fraternity, dignity and unity"],
      "The 42nd Amendment inserted 'socialist' and 'secular' and changed 'unity of the Nation' to 'unity and integrity of the Nation'. It is the only amendment so far to the Preamble."),
    S(2, 2, "Sources of the Constitution", "The idea of the Directive Principles of State Policy was borrowed from the constitution of which country?",
      ["Ireland", "United States", "United Kingdom", "Canada"],
      "The Directive Principles (Part IV) are modelled on the Irish Constitution. Fundamental Rights draw on the US Constitution and parliamentary government on the UK."),
    S(2, 1, "Parliament", "How many members can the President nominate to the Rajya Sabha?",
      ["12", "2", "10", "14"],
      "Article 80 allows the President to nominate 12 members with special knowledge of literature, science, art or social service."),
    S(2, 1, "State government", "Who appoints the Governor of a state?",
      ["The President", "The Chief Minister", "The Prime Minister", "The Chief Justice of India"],
      "Under Article 155 the Governor is appointed by the President by warrant under his hand and seal."),
    S(2, 2, "Local government", "Panchayati Raj institutions got constitutional status through which amendment?",
      ["73rd Amendment", "74th Amendment", "42nd Amendment", "61st Amendment"],
      "The 73rd Amendment Act of 1992 added Part IX on panchayats. The 74th Amendment did the same for urban local bodies, and the 61st lowered the voting age to 18."),
    S(2, 1, "Parliament", "Unless dissolved earlier, what is the normal term of the Lok Sabha?",
      ["5 years", "6 years", "4 years", "7 years"],
      "Article 83 fixes the Lok Sabha's term at five years from its first meeting. The Rajya Sabha is a permanent House whose members serve six-year terms."),
    S(2, 1, "Ancient India", "Who wrote the Arthashastra?",
      ["Kautilya", "Kalidasa", "Megasthenes", "Banabhatta"],
      "The Arthashastra, a treatise on statecraft, is attributed to Kautilya (Chanakya), adviser to Chandragupta Maurya. Megasthenes wrote Indica and Banabhatta wrote Harshacharita."),
    S(2, 1, "Ancient India", "After which war did the emperor Ashoka turn to Buddhism?",
      ["Kalinga War", "Battle of the Hydaspes", "Battle of Tarain", "Battle of Plassey"],
      "The bloodshed of the Kalinga War (about 261 BCE) led Ashoka to give up conquest by war and embrace Buddhism, as his Rock Edict XIII records."),
    S(2, 1, "Medieval India", "Which Mughal emperor founded the city of Fatehpur Sikri?",
      ["Akbar", "Shah Jahan", "Jahangir", "Humayun"],
      "Akbar built Fatehpur Sikri in the 1570s, with the Buland Darwaza marking his Gujarat campaign."),
    S(2, 2, "Medieval India", "Who founded the Vijayanagara Empire in 1336?",
      ["Harihara I and Bukka Raya I", "Krishnadevaraya", "Pulakeshin II", "Rajendra Chola I"],
      "The brothers Harihara and Bukka of the Sangama dynasty founded Vijayanagara. Krishnadevaraya was its most famous later ruler; Pulakeshin II was a Chalukya king and Rajendra Chola I a Chola king."),
    S(2, 1, "Modern India", "In which year did Mahatma Gandhi begin the Dandi March (Salt Satyagraha)?",
      ["1930", "1920", "1942", "1928"],
      "The march from Sabarmati Ashram to Dandi began on 12 March 1930 and started the Civil Disobedience Movement."),
    S(2, 1, "Modern India", "Who gave the call 'Do or Die' at the start of the Quit India Movement in 1942?",
      ["Mahatma Gandhi", "Subhas Chandra Bose", "Jawaharlal Nehru", "Bal Gangadhar Tilak"],
      "Gandhi gave the call 'Do or Die' in his speech at Gowalia Tank, Bombay, on 8 August 1942."),

    # ---------- Drill only ----------
    S(0, 2, "Fundamental Rights", "Free and compulsory education for children aged 6 to 14 is a Fundamental Right under which Article?",
      ["Article 21A", "Article 45", "Article 24", "Article 51A"],
      "The 86th Amendment of 2002 inserted Article 21A. Article 45 is now a Directive Principle on early childhood care, Article 24 bans child labour in hazardous work, and Article 51A lists Fundamental Duties."),
    S(0, 1, "Parliament", "Who is the ex officio Chairman of the Rajya Sabha?",
      ["The Vice-President", "The President", "The Speaker", "The Prime Minister"],
      "Under Article 64 the Vice-President of India is the ex officio Chairman of the Rajya Sabha."),
    S(0, 1, "Modern India", "The Battle of Plassey in 1757 was fought between the British East India Company and:",
      ["Siraj-ud-Daulah", "Tipu Sultan", "Mir Qasim", "Hyder Ali"],
      "Robert Clive defeated Siraj-ud-Daulah, the Nawab of Bengal, at Plassey in 1757. Mir Qasim fought the Company at Buxar in 1764."),
    S(0, 2, "Ancient India", "Which Gupta ruler is called the 'Napoleon of India' for his conquests?",
      ["Samudragupta", "Chandragupta II", "Skandagupta", "Kumaragupta I"],
      "The historian V. A. Smith called Samudragupta the Napoleon of India, based on the conquests listed in the Allahabad Pillar inscription."),
]
